                    emit(n, &mut buf, &mut len);
                    push(b" =", &mut buf, &mut len);
                    let mut m = n;
                    while m % 2 == 0 {
                        push(b" 2", &mut buf, &mut len);
                        m /= 2;
                    }
                    let mut d: u64 = 3;
                    while d <= m / d {
                        while m % d == 0 {
                            push(b" ", &mut buf, &mut len);
                            emit(d, &mut buf, &mut len);
                            m /= d;
                        }
                        d += 2;
                    }
                    if m > 1 {
                        push(b" ", &mut buf, &mut len);
                        emit(m, &mut buf, &mut len);
                    }
