            if rest.is_empty() {
                crate::kprintln!("usage: adler32 <text>");
            } else {
                const MOD: u32 = 65521;
                let bytes = rest.as_bytes();
                let mut a: u32 = 1;
                let mut b: u32 = 0;
                for &byte in bytes {
                    a = (a + byte as u32) % MOD;
                    b = (b + a) % MOD;
                }
                let sum = (b << 16) | a;
                crate::kprintln!("adler32: 0x{:08x} ({} bytes)", sum, bytes.len());
            }
