                while (d as u128) * (d as u128) <= x as u128 {
                    if x % d == 0 {
                        distinct += 1;
                        let mut e = 0u32;
                        while x % d == 0 {
                            x /= d;
                            e += 1;
                        }
                        if e >= 2 {
                            return 0; // a squared prime divides n -> mu = 0
                        }
                    }
                    d += 1;
                }
                if x > 1 {
                    distinct += 1;
                }
                if distinct % 2 == 0 { 1 } else { -1 }
