                            let num = (b | 0x20) - b'a' + 1; // 1..=26
                            if num >= 10 && len < buf.len() {
                                buf[len] = b'0' + num / 10;
                                len += 1;
                            }
                            if len < buf.len() {
                                buf[len] = b'0' + num % 10;
                                len += 1;
                            }
