                        if i >= start {
                            if !first && len < buf.len() {
                                buf[len] = b' ';
                                len += 1;
                            }
                            first = false;
                            for &c in w.as_bytes() {
                                if len < buf.len() {
                                    buf[len] = c;
                                    len += 1;
                                }
                            }
                        }
