                    if rev == n {
                        crate::kprintln!(
                            "isbinpalindrome: {} ({}) IS a binary palindrome",
                            n, bstr
                        );
                    } else {
                        crate::kprintln!(
                            "isbinpalindrome: {} ({}) is NOT a binary palindrome",
                            n, bstr
                        );
                    }
