            fn is_prime(n: u64) -> bool {
                if n < 2 {
                    return false;
                }
                if n % 2 == 0 {
                    return n == 2;
                }
                let mut i = 3u64;
                while i * i <= n {
                    if n % i == 0 {
                        return false;
                    }
                    i += 2;
                }
                true
            }
